*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-page:       #0e1117;
  --bg-card:       #161b27;
  --bg-card-hover: #1c2333;
  --border:        #2a3249;
  --border-focus:  #7c9ef8;
  --accent:        #7c9ef8;
  --accent-glow:   rgba(124, 158, 248, 0.18);
  --text-primary:  #e6eaf4;
  --text-secondary:#9aa3b8;
  --text-answer:   #c8cedc;
  --icon-size:     1.1rem;
  --radius:        10px;
  --transition:    200ms ease;
}

body {
  background: var(--bg-page);
  color: var(--text-primary);
  font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
}

/* ── Skip link ────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #0e1117;
  font-weight: 700;
  border-radius: 0 0 var(--radius) var(--radius);
  text-decoration: none;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ── Page layout ──────────────────────────────────────────────── */
header {
  padding: 3.5rem 1rem 2.5rem;
  text-align: center;
  border-bottom: 1px solid var(--border);
  background: linear-gradient(180deg, #111827 0%, var(--bg-page) 100%);
}

header .cat-icon {
  font-size: 3rem;
  display: block;
  margin-bottom: 0.75rem;
  line-height: 1;
}

header h1 {
  font-size: clamp(1.6rem, 4vw, 2.4rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, #a8c0ff, #7c9ef8 50%, #c9b8ff);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

header p {
  margin-top: 0.5rem;
  color: var(--text-secondary);
  font-size: 1.05rem;
}

main {
  max-width: 760px;
  margin: 0 auto;
  padding: 2.5rem 1rem 4rem;
}

/* ── Section intro ────────────────────────────────────────────── */
.faq-intro {
  color: var(--text-secondary);
  font-size: 0.9rem;
  margin-bottom: 1.5rem;
  text-align: center;
}

/* ── FAQ list ─────────────────────────────────────────────────── */
.faq-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

/* ── Individual disclosure item ───────────────────────────────── */
.example {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.example:has(button[aria-expanded="true"]) {
  border-color: rgba(124, 158, 248, 0.4);
  box-shadow: 0 0 0 1px rgba(124, 158, 248, 0.15),
              0 4px 16px rgba(0, 0, 0, 0.4);
}

/* ── Question heading & trigger ───────────────────────────────── */
.example h3 { font-size: 1rem; }

.example h3 button {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.1rem 1.25rem;
  background: transparent;
  border: none;
  cursor: pointer;
  color: var(--text-primary);
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.4;
  text-align: left;
  transition: background var(--transition), color var(--transition);
  border-radius: var(--radius);
}

.example h3 button:hover {
  background: var(--bg-card-hover);
  color: #fff;
}

.example h3 button:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: -2px;
  background: var(--bg-card-hover);
}

/* chevron icon */
.example h3 button .chevron {
  flex-shrink: 0;
  width: var(--icon-size);
  height: var(--icon-size);
  color: var(--accent);
  transition: transform var(--transition);
  aria-hidden: true;
}

.example h3 button[aria-expanded="true"] .chevron {
  transform: rotate(180deg);
}

/* ── Answer panel ─────────────────────────────────────────────── */
.details {
  padding: 0 1.25rem 1.25rem 1.25rem;
  color: var(--text-answer);
  font-size: 0.97rem;
  line-height: 1.7;
  border-top: 1px solid var(--border);
  animation: slide-in var(--transition) ease-out;
}

.details p + p { margin-top: 0.75rem; }

@keyframes slide-in {
  from { opacity: 0; transform: translateY(-6px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ── Footer ───────────────────────────────────────────────────── */
footer {
  border-top: 1px solid var(--border);
  padding: 1.5rem 1rem;
  text-align: center;
  color: var(--text-secondary);
  font-size: 0.85rem;
}

/* ── Forced Colors (Windows High Contrast) ────────────────────── */
@media (forced-colors: active) {
  .example { border: 2px solid ButtonText; }
  .example h3 button { forced-color-adjust: auto; }
  .example h3 button:focus-visible { outline: 3px solid Highlight; }
  header h1 {
    -webkit-text-fill-color: unset;
    background: none;
    color: CanvasText;
  }
}

/* ── Reduced motion ───────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}

/* ── Reflow / narrow viewports ────────────────────────────────── */
@media (max-width: 400px) {
  header { padding: 2rem 1rem 1.5rem; }
  .example h3 button { padding: 0.9rem 1rem; font-size: 0.95rem; }
  .details { padding: 0 1rem 1rem 1rem; }
}
